    "description": "A store-bound product quantity selector. Renders its own compact stepper — a minus button, a number input, and a plus button — and owns the value locally (no children). specials.button toggles the +/− steppers (false → input-only). The shared +/− skin is styled through the quantity-button satellite; the input surface through the quantity-input satellite.",
    "useWhen": [
      "Product buy-box where the shopper picks how many units to add to cart",
      "Product card or quick-buy layout that needs a compact quantity stepper",
      "Any place a numeric +/− quantity control belongs before an add-to-cart action"
    ],
    "avoidWhen": [
      "Static quantity or inventory text — use text instead",
      "Generic numeric inputs not tied to purchase quantity",
      "Selecting between options/variants — use a select or tab instead"
    ],
    "contentTips": [
      "Use config.defaultNum for the initial visible quantity (defaults to 1)",
      "Use specials.button: true for minus/input/plus steppers, or false for input-only",
      "Do not add children — the input and optional buttons are rendered internally",
      "Style the shared plus/minus buttons through the quantity-button satellite; both buttons use the same skin",
      "Style the input surface through the quantity-input satellite"
    ],
    "semantics": [
      "product",
      "dataset",
      "store",
      "ecommerce",
      "quantity",
      "stepper"
    ]
